equation_logic_text:
var calc_output = [];
var msg, recs, mini_msg;
var u = parseInt(major_bleeding) + parseInt(creatinine) + parseInt(anemia) + parseInt(malignancy) + parseInt(pulmonary_embolism) + parseInt(age_75);
if (creatinine == 1.5) {
    u += .5
};
if (anemia == 1.5) {
    u += .5
};
if (u == 0) {
    msg = 'Low Risk.<br/>0.1% Risk of Major Bleeding';
    recs = 'Initiation of anticoagulation reasonable.';
    mini_msg = 'Low Risk of Major Bleeding.'
};
if (u > 0 && u < 5) {
    msg = 'Intermediate Risk.<br/>2.8% Risk of Major Bleeding';
    recs = 'Carefully consider risks and benefits of anticoagulation prior to starting therapy.';
    mini_msg = 'Intermediate Risk of Major Bleeding.'
};
if (u > 4) {
    msg = 'High Risk.<br/>6.2% Risk of Major Bleeding';
    recs = 'Alternative options should be considered unless there is a strong demonstrable clinical need for anticoagulation.';
    mini_msg = 'High Risk of Major Bleeding.'
};
calc_output.push({
    name: 'mini',
    value: u.toFixed(1),
    value_text: 'points',
    message: mini_msg
});
calc_output.push({
    name: '1786_RIETE Score_result',
    value: u.toFixed(1),
    value_text: 'points',
    message: msg + '<br/><br/>' + recs
});
